#Region @DOC
#### Description:
#This process executes an HTTP request from within a TurboIntegrator context. It wraps TM1's native `ExecuteHttpRequest` function with structured JSON-based parameter handling, automatic header management, response capture, and error handling. It is the standard Bedrock mechanism for integrating TM1 with external REST APIs, webhooks, and web services.
#
#### How to Use:
#`pMethod` defines the HTTP method for the request. It must be one of the standard HTTP verbs: `GET`, `POST`, `PUT`, `PATCH`, or `DELETE`. The value is converted to uppercase automatically.
#
#`pURL` is the full URL the request will be sent to. `pURLPath` is an optional string that will be appended to `pURL`. This is useful when the base URL is fixed but the path needs to be constructed dynamically.
#
#`pHeaders` is a JSON Array of header strings to include in the request. Each header must be in `Name:Value` format:
#```json
#["Authorization:Bearer eyJhbGci...", "Accept:application/json"]
#```
#For `POST`, `PUT`, and `PATCH` requests, if no `Content-Type` header is present in `pHeaders`, the process will automatically add:
#```
#Content-Type: application/json; charset=utf-8
#```
#
#`pBody` is the request body to send. For REST API calls this will typically be a JSON string. Leave it blank for methods that do not send a body, such as `GET` or `DELETE`:
#```json
#{"name": "New Item", "value": 42}
#```
#
#After the request executes, the process writes its result to the global string variable `sBedrockReturnValue` as a JSON object containing the status code and response body:
#```json
#{
#  "status_code": 200,
#  "body": {"id": "abc123", "status": "ok"}
#}
#```
#If the response body is not valid JSON, it will be wrapped as a JSON string. To read values from this in a downstream process:
#```
#nStatus = StringToNumber( JsonToString( sBedrockReturnValue, '/status_code' ) );
#sId     = JsonToString( sBedrockReturnValue, '/body/id' );
#```
#
#> [!NOTE]
#> Response bodies with a `Content-Type` of `application/octet-stream` are not captured in `sBedrockReturnValue`. Use `pResponseFile` to persist binary responses to disk instead.
#
#`pResponseHeaders` is a JSON Array of response header names you want captured in the return value. Any headers listed here will be retrieved from the HTTP response and added under a `headers` key in `sBedrockReturnValue`. For example, passing `["Content-Type", "X-Request-Id"]` would produce:
#```json
#{
#  "status_code": 200,
#  "body": {"id": "abc123"},
#  "headers": {
#    "Content-Type": "application/json",
#    "X-Request-Id": "abc-123"
#  }
#}
#```
#
#Here is a full example calling a REST API with a `POST` request, passing an authorisation header and capturing the response:
#```json
#{
#  "pMethod":   "POST",
#  "pURL":      "https://api.example.com/items",
#  "pUser":     "admin:password",
#  "pBody":     "{\"name\": \"New Item\", \"value\": 42}",
#  "pHeaders":  ["Authorization:Bearer eyJhbGciOiJSUzI1..."],
#  "pLogOutput": 1
#}
#```
#
#Here is the same call sending a webhook notification to Microsoft Teams, where no authentication or response parsing is needed:
#```json
#{
#  "pMethod": "POST",
#  "pURL":    "https://outlook.office.com/webhook/...",
#  "pBody":   "{\"text\": \"TM1 process completed successfully.\"}"
#}
#```
#
#> [!NOTE]
#> `pUser` passes credentials as a `-u` curl-style basic auth flag. If the endpoint uses token-based authentication, leave `pUser` blank and pass your token via `pHeaders` using an `Authorization:Bearer ...` header instead.
#
#- `pMethod` - The HTTP method to use for the request (`GET`, `POST`, `PUT`, `PATCH`, `DELETE`).
#- `pURL` - The full URL to send the request to.
#- `pURLPath` - Optional path string to append to `pURL`.
#- `pUser` - Basic auth credentials in `username:password` format. Leave blank if not required.
#- `pHeaders` - JSON Array of `Name:Value` header strings to include in the request.
#- `pBody` - The request body. Typically a JSON string for REST API calls.
#- `pResponseFile` - Server-side file path to write the raw response body to. Useful for large payloads or binary responses.
#- `pResponseHeaders` - JSON Array of response header names to capture in `sBedrockReturnValue`.
#- `pCertificateFile` - Path to a custom CA certificate file (`.pem` or `.crt`) for TLS verification.
#- `pContext` - Value for the `TM1-SessionContext` request header. Defaults to `BedrockTop`. Override this to identify the source of requests in TM1 server logs.
#- `pVerify` - Controls TLS certificate verification. `0` (default) skips verification (`-k`), suitable for internal or self-signed certificate environments. `1` enforces verification.
#- `pLogOutput` - Write parameters, request info, and response info to the server message log (`0` = off, `1` = on).
#- `pStrictErrorHandling` - If `1`, any HTTP response with a status code of `400` or above will call `ItemReject`, resulting in a minor error status on the process. If `0` (default), HTTP errors are silently captured in `sBedrockReturnValue` and the process continues.
#- `pJson` - JSON Object to pass all parameters at once. Overrides individually passed parameters for any keys included.
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants ###
cThisProcName   = GetProcessName();
cUserName       = TM1User();
cTimeStamp      = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt      = NumberToString( INT( RAND( ) * 1000 ));
cTemp           = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sMessages       = '{"Process": "'|cThisProcName|'", "User": "'|cUsername|'", "Info": ["Process: '''|cThisProcName|''' run by User: '''|cUsername|'''."], "Error": []}';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );
sMessages = '{"Process": "'|GetProcessName()|'", "User": "'|TM1User()|'", "Info": ["Process: '''|GetProcessName()|''' run by User: '''|TM1User()|'''."], "Error": []}';
pDefaultParameters = '{
  "pBody":                "",
  "pCertificateFile":     "",
  "pContext":             "BedrockTop",
  "pHeaders":             "[]",
  "pMethod":              null,
  "pResponseFile":        "",
  "pResponseHeaders":     "[]",
  "pURL":                 null,
  "pURLPath":             "",
  "pUser":                null,
  "pLogOutput":           0,
  "pStrictErrorHandling": 0,
  "pVerify":              0
}';

pPassedParameters = '{
  "pBody":                '|StringToJson  ( pBody                )|',
  "pCertificateFile":     '|StringToJson  ( pCertificateFile     )|',
  "pContext":             '|StringToJson  ( pContext             )|',
  "pHeaders":             '|StringToJson  ( pHeaders             )|',
  "pMethod":              '|StringToJson  ( pMethod              )|',
  "pResponseFile":        '|StringToJson  ( pResponseFile        )|',
  "pResponseHeaders":     '|StringToJson  ( pResponseHeaders     )|',
  "pURL":                 '|StringToJson  ( pURL                 )|',
  "pURLPath":             '|StringToJson  ( pURLPath             )|',
  "pUser":                '|StringToJson  ( pUser                )|',
  "pLogOutput":           '|NumberToString( pLogOutput           )|',
  "pStrictErrorHandling": '|NumberToString( pStrictErrorHandling )|',
  "pVerify":              '|NumberToString( pVerify              )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
# String Parameters
pBody                =                 JsonToString( pJson, '/pBody'                );
pCertificateFile     =                 JsonToString( pJson, '/pCertificateFile'     );
pContext             =                 JsonToString( pJson, '/pContext'             );
pHeaders             =                 JsonToString( pJson, '/pHeaders'             );
pMethod              =                 JsonToString( pJson, '/pMethod'              );
pResponseFile        =                 JsonToString( pJson, '/pResponseFile'        );
pResponseHeaders     =                 JsonToString( pJson, '/pResponseHeaders'     );
pURL                 =                 JsonToString( pJson, '/pURL'                 );
pURLPath             =                 JsonToString( pJson, '/pURLPath'             );
pUser                =                 JsonToString( pJson, '/pUser'                );
# Numeric Parameters
pLogOutput           = StringToNumber( JsonToString( pJson, '/pLogOutput'           ) );
pStrictErrorHandling = StringToNumber( JsonToString( pJson, '/pStrictErrorHandling' ) );
pVerify              = StringToNumber( JsonToString( pJson, '/pVerify'              ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

### LogOutput parameters
nSize = JsonSize( pJson );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  sKey = JsonGetKey( pJson, nSize );
  pPassedParameters = JsonReplace( pPassedParameters, sKey, JsonGet( pJson, sKey ) );
END;

sMessages = JsonAdd( sMessages, '/Info/0', pPassedParameters );
IF( pLogOutput = 1 );
  LogOutput('INFO', JsonToString( sMessages, '/Info/0' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

#################################################################################################
#Region - Validate Parameters

IF( JsonType( pHeaders ) @<> 'array' );
  pHeaders = '[]';
ENDIF;

### If errors occurred terminate process with a major error status ###
IF( JsonSize( sMessages, '/Error' ) <> 0 );
    ProcessBreak;
ENDIF;

#EndRegion - Validate Parameters
#################################################################################################

#################################################################################################
#Region - Compile Parameters into JSON Array sRequestOptions (sRO)

pMethod = UPPER( pMethod );
sURL = pURL;
sRO = '[]';

# pUser
IF( pUser @<> '' );
  sRO = JsonAdd( sRO, '', StringToJson( '-u '|pUser ) );
ENDIF;

# pHeaders
sHeadersType = JsonType( pHeaders );
IF(sHeadersType @<> 'array' );
  IF( sHeadersType @<> 'string' );
    pHeaders = StringToJson( pHeaders );
  ENDIF;
  pHeaders = JsonAdd( '[]', '', pHeaders );
ENDIF;

nContentTypeSpecified = 0;
WHILE( JsonSize( pHeaders ) > 0 );
  sHeader = JsonToString( pHeaders, 0 );
  IF( SUBST( sHeader, 1, 13 ) @= 'Content-Type:' );
    nContentTypeSpecified = 1;
  ENDIF;
  sRO = JsonAdd( sRO, '', StringToJson( '-h '|sHeader ) );
  pHeaders = JsonRemove( pHeaders, 0 );
END;

# Add a Content-Type for specific Methods
IF( ( pMethod @= 'POST' % pMethod @= 'PATCH' % pMethod @= 'PUT' ) & nContentTypeSpecified = 0 );
  sRO = JsonAdd( sRO, '', StringToJson( '-h Content-Type:application/json; charset=utf-8' ) );
ENDIF;

IF( pContext @<> '' );
  sRO = JsonAdd( sRO, '', StringToJson( '-h TM1-SessionContext:'|pContext ) );
ENDIF;

# pBody
IF( pBody @<> '' );
  sRO = JsonAdd( sRO, '', StringToJson( '-d '|pBody ) );
ENDIF;

# pResponseFile
IF( pResponseFile @<> '' );
  sRO = JsonAdd( sRO, '', StringToJson( '-o '|pResponseFile ) );
ENDIF;

# pCertificateFile
IF( pCertificateFile @<> '' );
  sRO = JsonAdd( sRO, '', StringToJson( '-c '|pCertificateFile ) );
ENDIF;

# pVerify
IF( pVerify = 0 );
  sRO = JsonAdd( sRO, '', '"-k"' );
ENDIF;
  

##EndRegion - Compile Parameters into JSON Array sRequestOptions (sRO)
