  pResponseHeaders = JsonRemove( pResponseHeaders, 0 );
END;

sMessages = JsonAdd( sMessages, '/Info/0', StringToJson( 'ExecuteHttpRequest Request: '| sRequestInfo ) );
IF( pLogOutput = 1 ); LogOutput( 'INFO', JsonToString( sMessages, '/Info/0' ) ); ENDIF;

sBedrockReturnValue = sResponseInfo;
IF( pLogOutput = 1 ); LogOutput( 'INFO', JsonToString( 'ExecuteHttpRequest Response: '| sResponseInfo ) ); ENDIF;

# Error Handling
IF( pStrictErrorHandling = 1 & nStatusCode >= 400 );
  ItemReject( sResponseInfo );
ENDIF;


#EndRegion - Return Info
